#define STABLE_SAMPLES 5

// Anropas regelbundet, till exempel varje millisekund.
// Returnerar 1 precis när ett nytt tryck har godkänts.
uint8_t button_update(uint8_t raw_level) {
    static uint8_t stable = 0, count = 0;
    if (raw_level == stable) {
        count = 0;                      // studs tillbaka: börja om
    } else if (++count >= STABLE_SAMPLES) {
        stable = raw_level;             // ny nivå har hållit i sig
        count = 0;
        return stable == 1;             // stigande flank = tryck
    }
    return 0;
}
